import { CatalogueService } from "../application/catalogue-service";
import { OrderService } from "../application/order-service";
import { createApp } from "./http";
import {
  InMemoryOrderRepository,
  InMemoryProductRepository,
  SystemClock,
  UuidGenerator,
} from "./in-memory";

const products = new InMemoryProductRepository();
const orders = new InMemoryOrderRepository();

const catalogue = new CatalogueService(products);
const orderService = new OrderService(orders, products, new UuidGenerator(), new SystemClock());

// Seed a small demo catalogue.
catalogue.addProduct({ id: "widget", name: "Widget", priceCents: 1299, initialStock: 50 });
catalogue.addProduct({ id: "gadget", name: "Gadget", priceCents: 2499, initialStock: 20 });
catalogue.addProduct({ id: "gizmo", name: "Gizmo", priceCents: 999, initialStock: 5 });

const app = createApp({ catalogue, orders: orderService });
const port = Number(process.env["PORT"] ?? 3000);

app.listen(port, () => {
  console.log(`Order fulfilment API listening on http://localhost:${port}`);
});

